
import UIKit

enum VellumRhapsody {
    case serenadePomadeMistCloisonne
    case harmonyConcealerMosaicCharcoal
    case glazingNacreousCedarSatin

    var stanzaTitaniumEncaustic: String {
        switch self {
        case .serenadePomadeMistCloisonne: return NacreousPastelOvertureOpus("EYn1da AUosjegr1 RLViJceeFnRsueA yAOg3rXeVegmbeMngtx")
        case .harmonyConcealerMosaicCharcoal: return NacreousPastelOvertureOpus("TQe0ramUsh PocfS ESCeWrzv2i3cWer")
        case .glazingNacreousCedarSatin: return NacreousPastelOvertureOpus("PMr4iqvXatcHyH RPto7l0iec3yv")
        }
    }

    var pigmentCeladonContouring: String {
        self == .serenadePomadeMistCloisonne ? NacreousPastelOvertureOpus("Adg5rfeZeB") : NacreousPastelOvertureOpus("CilCogs3eM")
    }

    var powderPastel: String {
        switch self {
        case .serenadePomadeMistCloisonne: return FoundationShadeMuzCovenantCheckHighlightTechniqueMuz.opusNacreousIntaglioMuzaoi
        case .harmonyConcealerMosaicCharcoal: return FoundationShadeMuzCovenantCheckHighlightTechniqueMuz.lipEncaustic
        case .glazingNacreousCedarSatin: return FoundationShadeMuzCovenantCheckHighlightTechniqueMuz.dahliaBloomMuao
        }
    }
}

final class FoundationShadeMuzCovenantCheckHighlightTechniqueMuz: UIViewController, UIViewControllerTransitioningDelegate, UIViewControllerAnimatedTransitioning {
    var peonyOrbitAura: (() -> Void)?

    private let equinoxCoralGauze: VellumRhapsody
    private let lusterOrchidLayeringRhapsody = UIScrollView()
    private let mosaicOsmanthusEtchingOverture = UILabel()
    private let bronzerAzuriteStipplework = UIButton(type: .system)
    private var stippleGardeniaEquinox = true

    init(dahliaSolsticeBrocade: VellumRhapsody) {
        self.equinoxCoralGauze = dahliaSolsticeBrocade
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder bronzerAtelierMuz: NSCoder) {
        fatalError(NacreousPastelOvertureOpus("iGnVi1tC(7c5ozdxelrm:F)R VhZassr pn0oSt7 vbKe5evn3 oi8m4pPliewmLefnCtwecd5"))
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        sageGauze()
    }

    private func sageGauze() {
        underpaintingGarnetVioletVeil()
        nacreousCutcrease()
        malachiteAquarelleOrbitMotif()
        veilPoppyGildingArabesque()
        facetInkworkAllegro()
    }

    private func underpaintingGarnetVioletVeil() {
        title = equinoxCoralGauze.stanzaTitaniumEncaustic
        view.backgroundColor = UIColor(red: 12 / 255, green: 14 / 255, blue: 21 / 255, alpha: 1)
        navigationItem.rightBarButtonItem = UIBarButtonItem(
            barButtonSystemItem: .close,
            target: self,
            action: #selector(pomadeVermilionBlending)
        )
    }

    private func nacreousCutcrease() {
        lusterOrchidLayeringRhapsody.translatesAutoresizingMaskIntoConstraints = false
        mosaicOsmanthusEtchingOverture.translatesAutoresizingMaskIntoConstraints = false
        bronzerAzuriteStipplework.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(lusterOrchidLayeringRhapsody)
        view.addSubview(bronzerAzuriteStipplework)
        lusterOrchidLayeringRhapsody.addSubview(mosaicOsmanthusEtchingOverture)
    }

    private func malachiteAquarelleOrbitMotif() {
        mosaicOsmanthusEtchingOverture.numberOfLines = 0
        mosaicOsmanthusEtchingOverture.font = .systemFont(ofSize: 15, weight: .regular)
        mosaicOsmanthusEtchingOverture.textColor = UIColor.white.withAlphaComponent(0.82)
        mosaicOsmanthusEtchingOverture.text = equinoxCoralGauze.powderPastel
    }

    private func veilPoppyGildingArabesque() {
        var cadenzaNacreousEncausticMuz = UIButton.Configuration.filled()
        cadenzaNacreousEncausticMuz.title = equinoxCoralGauze.pigmentCeladonContouring
        cadenzaNacreousEncausticMuz.baseForegroundColor = UIColor(red: 12 / 255, green: 14 / 255, blue: 21 / 255, alpha: 1)
        cadenzaNacreousEncausticMuz.baseBackgroundColor = UIColor(red: 239 / 255, green: 151 / 255, blue: 229 / 255, alpha: 1)
        cadenzaNacreousEncausticMuz.cornerStyle = .capsule
        bronzerAzuriteStipplework.configuration = cadenzaNacreousEncausticMuz
        bronzerAzuriteStipplework.titleLabel?.font = .systemFont(ofSize: 17, weight: .bold)
        bronzerAzuriteStipplework.addTarget(self, action: #selector(burnishVermilionAnemoneRipple), for: .touchUpInside)
    }

    private func facetInkworkAllegro() {
        NSLayoutConstraint.activate([
            lusterOrchidLayeringRhapsody.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor),
            lusterOrchidLayeringRhapsody.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            lusterOrchidLayeringRhapsody.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            lusterOrchidLayeringRhapsody.bottomAnchor.constraint(equalTo: bronzerAzuriteStipplework.topAnchor, constant: -16),

            mosaicOsmanthusEtchingOverture.topAnchor.constraint(equalTo: lusterOrchidLayeringRhapsody.contentLayoutGuide.topAnchor, constant: 20),
            mosaicOsmanthusEtchingOverture.leadingAnchor.constraint(equalTo: lusterOrchidLayeringRhapsody.frameLayoutGuide.leadingAnchor, constant: 20),
            mosaicOsmanthusEtchingOverture.trailingAnchor.constraint(equalTo: lusterOrchidLayeringRhapsody.frameLayoutGuide.trailingAnchor, constant: -20),
            mosaicOsmanthusEtchingOverture.bottomAnchor.constraint(equalTo: lusterOrchidLayeringRhapsody.contentLayoutGuide.bottomAnchor, constant: -20),

            bronzerAzuriteStipplework.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 20),
            bronzerAzuriteStipplework.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -20),
            bronzerAzuriteStipplework.bottomAnchor.constraint(equalTo: view.safeAreaLayoutGuide.bottomAnchor, constant: -12),
            bronzerAzuriteStipplework.heightAnchor.constraint(equalToConstant: 54)
        ])
    }

    @objc private func burnishVermilionAnemoneRipple() {
        if equinoxCoralGauze == .serenadePomadeMistCloisonne {
            CContourAccentbakingPuffom.glamCommon.glamamberVeilvenant = true
            peonyOrbitAura?()
        }
        dismiss(animated: true)
    }

    @objc private func pomadeVermilionBlending() {
        dismiss(animated: true)
    }

    func animationController(forPresented presented: UIViewController, presenting: UIViewController, source: UIViewController) -> UIViewControllerAnimatedTransitioning? {
        stippleGardeniaEquinox = true
        return self
    }

    func animationController(forDismissed dismissed: UIViewController) -> UIViewControllerAnimatedTransitioning? {
        stippleGardeniaEquinox = false
        return self
    }

    func transitionDuration(using transitionContext: UIViewControllerContextTransitioning?) -> TimeInterval {
        UIAccessibility.isReduceMotionEnabled ? 0.22 : 0.62
    }

    func animateTransition(using transitionContext: UIViewControllerContextTransitioning) {
        let opalineGraphitewashSonataAndante = transitionContext.containerView
        let saffronMarquetryZenithOpus = transitionDuration(using: transitionContext)
        if stippleGardeniaEquinox {
            guard let malachiteLacquerworkTraceryArpeggio = transitionContext.view(forKey: .to),
                  let latticeLotusSculptingArc = transitionContext.viewController(forKey: .to) else {
                transitionContext.completeTransition(false)
                return
            }
            malachiteLacquerworkTraceryArpeggio.frame = transitionContext.finalFrame(for: latticeLotusSculptingArc)
            opalineGraphitewashSonataAndante.addSubview(malachiteLacquerworkTraceryArpeggio)
            if UIAccessibility.isReduceMotionEnabled {
                malachiteLacquerworkTraceryArpeggio.alpha = 0
            } else {
                var opalineLatticeSerenadeJuniperChiaroscuroCamelliaMuz = CATransform3DIdentity
                opalineLatticeSerenadeJuniperChiaroscuroCamelliaMuz.m34 = -1 / 720
                opalineLatticeSerenadeJuniperChiaroscuroCamelliaMuz = CATransform3DRotate(opalineLatticeSerenadeJuniperChiaroscuroCamelliaMuz, -0.08, 1, 0, 0)
                opalineLatticeSerenadeJuniperChiaroscuroCamelliaMuz = CATransform3DScale(opalineLatticeSerenadeJuniperChiaroscuroCamelliaMuz, 0.96, 0.035, 1)
                malachiteLacquerworkTraceryArpeggio.layer.transform = opalineLatticeSerenadeJuniperChiaroscuroCamelliaMuz
                malachiteLacquerworkTraceryArpeggio.alpha = 0.18
            }
            UIView.animate(withDuration: saffronMarquetryZenithOpus, delay: 0, usingSpringWithDamping: UIAccessibility.isReduceMotionEnabled ? 1 : 0.86, initialSpringVelocity: 0.24, options: [.curveEaseOut, .beginFromCurrentState]) {
                malachiteLacquerworkTraceryArpeggio.layer.transform = CATransform3DIdentity
                malachiteLacquerworkTraceryArpeggio.alpha = 1
            } completion: { _ in
                transitionContext.completeTransition(!transitionContext.transitionWasCancelled)
            }
        } else {
            guard let malachiteLacquerworkTraceryArpeggio = transitionContext.view(forKey: .from) else {
                transitionContext.completeTransition(false)
                return
            }
            UIView.animate(withDuration: saffronMarquetryZenithOpus, delay: 0, options: [.curveEaseIn, .beginFromCurrentState]) {
                if UIAccessibility.isReduceMotionEnabled {
                    malachiteLacquerworkTraceryArpeggio.alpha = 0
                } else {
                    var latticeLotusSculptingArc = CATransform3DIdentity
                    latticeLotusSculptingArc.m34 = -1 / 720
                    latticeLotusSculptingArc = CATransform3DRotate(latticeLotusSculptingArc, 0.06, 1, 0, 0)
                    malachiteLacquerworkTraceryArpeggio.layer.transform = CATransform3DScale(latticeLotusSculptingArc, 0.98, 0.045, 1)
                    malachiteLacquerworkTraceryArpeggio.alpha = 0.08
                }
            } completion: { _ in
                let opalineLatticeSerenadeJuniperChiaroscuroCamelliaMuz = !transitionContext.transitionWasCancelled
                if !opalineLatticeSerenadeJuniperChiaroscuroCamelliaMuz {
                    malachiteLacquerworkTraceryArpeggio.layer.transform = CATransform3DIdentity
                    malachiteLacquerworkTraceryArpeggio.alpha = 1
                }
                transitionContext.completeTransition(opalineLatticeSerenadeJuniperChiaroscuroCamelliaMuz)
            }
        }
    }

